-- Correct the frozen-author projection. No historical rows or frozen files change.
CREATE OR REPLACE FUNCTION app.semester_collection(who uuid,sid uuid,needs_review boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$
DECLARE result jsonb;BEGIN result:=app.semester_collection_r06(who,sid,needs_review);RETURN jsonb_build_object('items',(SELECT coalesce(jsonb_agg(x||jsonb_build_object('workflow',app.academic_flow_state(who,sid,(x->>'id')::uuid),'feedback',(SELECT comment FROM app.checkpoint_decisions WHERE project_id=(x->>'id')::uuid ORDER BY decided_at DESC LIMIT 1),'submitter',(SELECT author->>'name' FROM jsonb_array_elements((SELECT authors_snapshot FROM app.project_submissions WHERE id=(x->>'final')::uuid)) author WHERE (author->>'lead')::boolean LIMIT 1),'authorCount',(SELECT count(*) FROM app.project_authors WHERE project_id=(x->>'id')::uuid))),'[]') FROM jsonb_array_elements(result->'items') x));END $$;
